from typing import Optional, Set

from configuration_compiler.column_transformation.ids_mapping_helper import IdsMappingHelper
from configuration_compiler.column_transformation.relationships_generator import Relationship
from configuration_compiler.config_files_models.adapter.ext_model import AdapterModel
from configuration_compiler.config_files_models.adapter.model import SourceField, SourceTable, TargetField
from configuration_compiler.config_files_models.common.field_type import CommonParsing
from configuration_compiler.config_files_models.utils.target_table_schema_utils import TargetTableSchemaUtils
from configuration_compiler.spec_models.target_table_schema import TargetTableSchemaExt
from common.model.types import TargetId
from dmf.model.target_configuration.target_table_schema import ForeignKey
from dmf.model.target_configuration.target_transformation import ColumnTransformation


class ForeignKeysTransformationsGenerator:
    """
    This class is responsible for generating foreign key transformations.

    The algorithm for generating foreign key transformations works as follows:
    1. It first retrieves the source and target fields that are primary keys. Without finding such fields, it cannot generate any foreign key transformations.
        This is because foreign keys are always generated from primary keys.
    2. If no such fields exist, it returns an empty set.
    3. For each foreign key in the relationship, it generates a transformation and adds it to the set of transformations.
    4. The transformation for a foreign key is generated by mapping the foreign key to the corresponding source and target fields.

    Attributes:
    - dmf_adaptor: An instance of AdapterModel which provides methods to interact with the source and target fields.
    - relationship: An instance of Relationship which represents the relationship between source and target tables.
    - source_table: An instance of SourceTable which represents the source table in the transformation.
    - target_tables_schemas: A dictionary mapping target IDs to their corresponding TargetTableSchemaExt instances.
    - ids_mapping_helper: An instance of IdsMappingHelper which helps in mapping IDs.

    Methods:
    - generate_fks_transformations: Generates a set of ColumnTransformation instances for the foreign keys in the relationship.
    - _get_pk_source_and_target_fields: Returns a tuple of SourceField and TargetField instances which are primary keys.
    - _is_target_field_pk: Checks if a given target field is a primary key.
    - _generate_fk_transformation: Generates a ColumnTransformation instance for a given foreign key.
    """

    def __init__(
        self,
        dmf_adaptor: AdapterModel,
        relationship: Relationship,
        source_table: SourceTable,
        target_tables_schemas: dict[TargetId, TargetTableSchemaExt],
        ids_mapping_helper: IdsMappingHelper,
    ):
        self._dmf_adaptor = dmf_adaptor
        self._relationship = relationship
        self._source_table = source_table
        self._target_tables_schemas = target_tables_schemas
        self._ids_mapping_helper = ids_mapping_helper

    def generate_fks_transformations(self) -> Set[ColumnTransformation]:
        source_and_target_field = self._get_pk_source_and_target_fields()
        if source_and_target_field is None:
            return set()
        source_field, target_field = source_and_target_field
        transformations = set()
        for fk in self._relationship.relation.foreign_keys:
            transformations.add(self._generate_fk_transformation(fk, self._relationship, source_field, target_field))
        return transformations

    def _get_pk_source_and_target_fields(self) -> Optional[tuple[SourceField, TargetField]]:
        required_table = self._relationship.destination.id
        for source_field in self._dmf_adaptor.source_fields_on_source_table(self._source_table):
            for target_field in self._dmf_adaptor.target_fields_on_source_field(source_field):
                if not self._is_target_field_pk(target_field):
                    continue
                table_and_parent = (
                    required_table,
                    TargetTableSchemaUtils.parent_table(self._target_tables_schemas[required_table]),
                )
                for table_name in table_and_parent:
                    if table_name == target_field.tableName:
                        for fk in self._relationship.relation.foreign_keys:
                            if target_field.targetField is not None:
                                if target_field.targetField != fk.from_attribute:
                                    continue
                            if target_field.fieldName == fk.to_attribute:
                                return source_field, target_field
        return None

    def _is_target_field_pk(self, target_field: TargetField) -> bool:
        col = TargetTableSchemaUtils.get_column(
            self._target_tables_schemas[target_field.tableName], target_field.fieldName
        )
        return col.is_primary_key

    def _generate_fk_transformation(
        self, fk: ForeignKey, relationship: Relationship, source_field: SourceField, target_field: TargetField
    ) -> ColumnTransformation:
        target_table_id = relationship.origin.id
        target_field_name = fk.from_attribute
        target_column = TargetTableSchemaUtils.get_column(self._target_tables_schemas[target_table_id], target_field_name)
        bypass_key_harmonization = bool(
            self._source_table.bypassKeysHarmonization and not source_field.enforceKeyHarmonization
        )
        should_be_id_mapped = self._ids_mapping_helper.should_map(
            bypass_key_harmonization, target_table_id, target_field_name
        )
        ct = ColumnTransformation(
            transformation_target_id=target_table_id,
            original_source_field_name=source_field.fieldName,
            target_field_name=target_field_name,
            target_field_type=relationship.get_fk_type(fk),
            source_field_type=CommonParsing.parse_field_type(source_field.fieldType),
            target_field_value=None,  # a fk should be generated, not a literal value
            is_source_primary_key=target_column.is_primary_key,
            target_field_condition=target_field.condition,
            owner_target_id=relationship.destination.id,
            should_be_id_mapped=should_be_id_mapped,
            has_source_field=True,
        )

        return ct
